update_rule.pseudocode:
if t == 0:
  generate_watts_strogatz_graph(N=population_size, k=average_degree, beta=rewiring_prob, seed=random_seed)
  for each person i:
    person[i].social_neighbors = neighbors(i)
else:
  no update (static network)

contacts = []
for each person i:
  # Determine today's itinerary based on occupation and mobility rate
  locs = sample_locations_for_person(i, mobility_rate, day)
  for each loc in locs:
    n_contacts = Poisson(adjusted_contact_rate(loc, policy.mandate_active))
    partners = sample_without_replacement(occupants(loc), n_contacts)
    for j in partners:
      if i < j: contacts.append((i,j,loc))
observable.contacts_daily = len(contacts)
contacts.daily_pairs_by_location = contacts

fines = 0
if policy.mandate_active:
  for each person i visiting public locations today:
    if person[i].mask_wearing_correctly == False:
      if Bernoulli(mandate_enforcement_prob * mean_location_enforcement):
        fines += 1
        # Increase compliance propensity and risk perception slightly
        person[i].compliance_propensity = clip(person[i].compliance_propensity + enforcement_compliance_bump, 0, 1)
        person[i].risk_perception = clip(person[i].risk_perception + enforcement_risk_bump, 0, 1)
observable.fines_issued_daily = fines

new_inf_cf = 0
for (i,j,loc) in contacts.daily_pairs_by_location:
  for (src, dst) in [(i,j),(j,i)]:
    if infection_state[src] == 'I' and infection_state[dst] == 'S':
      loc_multiplier = location_risk_multiplier(loc)
      presymp = presymptomatic_transmission_factor if person[src].days_since_infection < incubation_period_days else 1.0
      p_cf = base_transmission_prob * loc_multiplier * presymp
      if Bernoulli(p_cf):
        new_inf_cf += 1
observable.infections_daily_counterfactual = new_inf_cf
